From a6e286b90f66b3f205c2601d527c1829ed343cf1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:38:57 +0100
Subject: [PATCH] applet: allow hiding applications from the Applications tab

Streams that are always there but never need changing, like effect
processors, clutter the list. Each stream's menu now has a "Hide" item that
remembers the application, and the applet menu can show hidden ones again.

BUG: 523166
---
 applet/ListItemBase.qml  |  7 +++++-
 applet/main.qml          | 50 ++++++++++++++++++++++++++++++++++++----
 applet/main.xml          |  4 ++++
 src/qml/listitemmenu.cpp | 40 ++++++++++++++++++++++++++++++++
 src/qml/listitemmenu.h   | 17 ++++++++++++++
 5 files changed, 112 insertions(+), 6 deletions(-)

diff --git a/applet/ListItemBase.qml b/applet/ListItemBase.qml
index 83fab21f..2597b970 100644
--- a/applet/ListItemBase.qml
+++ b/applet/ListItemBase.qml
@@ -26,10 +26,12 @@ PC3.ItemDelegate {
     property string /* "sink" | "sink-input" | "source" | "source-output" */ type
     property string fullNameToShowOnHover: ""
     readonly property bool isStream: item.type === "sink-input" || item.type === "source-output"
+    readonly property string hideKey: isStream ? main.streamHideKey(item.type, item.model.PulseObject) : ""
+    readonly property bool hidden: hideKey !== "" && main.hiddenStreams.includes(hideKey)

     highlighted: dropArea.containsDrag
     background.visible: highlighted
-    opacity: (main.draggedStream && main.draggedStream.deviceIndex === item.model.Index) ? 0.3 : 1.0
+    opacity: (main.draggedStream && main.draggedStream.deviceIndex === item.model.Index) ? 0.3 : (item.hidden ? 0.6 : 1.0)
     checked: defaultButton.visible ? defaultButton.checked : !muteButton.checked
     Accessible.name: label
     Accessible.description: percentText.text
@@ -395,6 +397,9 @@ PC3.ItemDelegate {
         id: contextMenu
         pulseObject: item.model.PulseObject
         cardModel: main.paCardModel
+        hideableName: item.isStream ? main.streamAppName(item.model.PulseObject) : ""
+        hidden: item.hidden
+        onHideToggled: hidden => main.setStreamHidden(item.hideKey, hidden)
         itemType: {
             switch (item.type) {
             case "sink":
diff --git a/applet/main.qml b/applet/main.qml
index 1e44cded..d6f71829 100644
--- a/applet/main.qml
+++ b/applet/main.qml
@@ -37,6 +37,8 @@ PlasmoidItem {
     property QtObject draggedStream: null

     property bool showVirtualDevices: Plasmoid.configuration.showVirtualDevices
+    property bool showHiddenStreams: false
+    readonly property list<string> hiddenStreams: Plasmoid.configuration.hiddenStreams

     property bool micTestActive: false

@@ -174,20 +176,49 @@ PlasmoidItem {
     // non-virtual streams going to output devices
     readonly property PulseObjectFilterModel paSinkInputFilterModel: PulseObjectFilterModel {
         id: paSinkInputFilterModel
-        filters: [
-            { role: "VirtualStream", value: false },
-            { role: "Client", value: (client) => client.name !== "libcanberra" },
-        ]
+        filters: {
+            const hidden = main.showHiddenStreams ? [] : main.hiddenStreams;
+            return [
+                { role: "VirtualStream", value: false },
+                { role: "Client", value: (client) => client.name !== "libcanberra" },
+                { role: "PulseObject", value: (stream) => !hidden.includes(main.streamHideKey("sink-input", stream)) },
+            ];
+        }
         sourceModel: paSinkInputModel
     }

     // non-virtual streams coming from input devices
     readonly property PulseObjectFilterModel paSourceOutputFilterModel: PulseObjectFilterModel {
         id: paSourceOutputFilterModel
-        filters: [ { role: "VirtualStream", value: false } ]
+        filters: {
+            const hidden = main.showHiddenStreams ? [] : main.hiddenStreams;
+            return [
+                { role: "VirtualStream", value: false },
+                { role: "PulseObject", value: (stream) => !hidden.includes(main.streamHideKey("source-output", stream)) },
+            ];
+        }
         sourceModel: paSourceOutputModel
     }

+    function streamAppName(stream: QtObject): string {
+        return stream.properties["application.name"] || stream.client?.name || stream.name;
+    }
+
+    function streamHideKey(type: string, stream: QtObject): string {
+        return type + ":" + streamAppName(stream);
+    }
+
+    function setStreamHidden(key: string, hidden: bool): void {
+        const keys = main.hiddenStreams.filter(k => k !== key);
+        if (hidden) {
+            keys.push(key);
+        }
+        Plasmoid.configuration.hiddenStreams = keys;
+        if (keys.length === 0) {
+            main.showHiddenStreams = false;
+        }
+    }
+
     readonly property CardModel paCardModel: CardModel {
         id: paCardModel

@@ -782,6 +813,15 @@ PlasmoidItem {
             checkable: true
             checked: plasmoid.configuration.showVirtualDevices
             onTriggered: Plasmoid.configuration.showVirtualDevices = !Plasmoid.configuration.showVirtualDevices
+        },
+        PlasmaCore.Action {
+            text: i18n("Show hidden applications")
+            icon.name: "view-visible"
+            checkable: true
+            checked: main.showHiddenStreams
+            visible: main.hiddenStreams.length > 0
+            enabled: main.hiddenStreams.length > 0
+            onTriggered: main.showHiddenStreams = !main.showHiddenStreams
         }
     ]

diff --git a/applet/main.xml b/applet/main.xml
index 54bf8518..b7fc56fc 100644
--- a/applet/main.xml
+++ b/applet/main.xml
@@ -41,6 +41,10 @@
     <entry name="showVirtualDevices" type="Bool">
       <default>false</default>
     </entry>
+    <entry name="hiddenStreams" type="StringList">
+      <label>Applications whose streams are hidden from the applet</label>
+      <default></default>
+    </entry>
     <entry name="migrated" type="Bool">
       <default>false</default>
     </entry>
diff --git a/src/qml/listitemmenu.cpp b/src/qml/listitemmenu.cpp
index 631e2cd7..45ad9df5 100644
--- a/src/qml/listitemmenu.cpp
+++ b/src/qml/listitemmenu.cpp
@@ -174,8 +174,39 @@ void ListItemMenu::setVisualParent(QQuickItem *visualParent)
     }
 }

+QString ListItemMenu::hideableName() const
+{
+    return m_hideableName;
+}
+
+void ListItemMenu::setHideableName(const QString &hideableName)
+{
+    if (m_hideableName != hideableName) {
+        m_hideableName = hideableName;
+        update();
+        Q_EMIT hideableNameChanged();
+    }
+}
+
+bool ListItemMenu::isHidden() const
+{
+    return m_hidden;
+}
+
+void ListItemMenu::setHidden(bool hidden)
+{
+    if (m_hidden != hidden) {
+        m_hidden = hidden;
+        Q_EMIT hiddenChanged();
+    }
+}
+
 bool ListItemMenu::checkHasContent()
 {
+    if (!m_hideableName.isEmpty()) {
+        return true;
+    }
+
     // If there are at least two sink/source devices to choose from.
     if (m_sourceModel && m_sourceModel->rowCount() > 1) {
         return true;
@@ -490,6 +521,15 @@ QMenu *ListItemMenu::createMenu()
         }
     }

+    if (!m_hideableName.isEmpty()) {
+        menu->addSeparator();
+        auto *hideAction = menu->addAction(QIcon::fromTheme(QStringLiteral("view-hidden")),
+                                           i18nc("@action:inmenu %1 is the name of an application", "Hide %1", m_hideableName));
+        hideAction->setCheckable(true);
+        hideAction->setChecked(m_hidden);
+        connect(hideAction, &QAction::triggered, this, &ListItemMenu::hideToggled);
+    }
+
     if (menu->isEmpty()) {
         delete menu;
         return nullptr;
diff --git a/src/qml/listitemmenu.h b/src/qml/listitemmenu.h
index 5b8d6b54..aa6361d0 100644
--- a/src/qml/listitemmenu.h
+++ b/src/qml/listitemmenu.h
@@ -37,6 +37,11 @@ class ListItemMenu : public QObject, public QQmlParserStatus

     Q_PROPERTY(QQuickItem *visualParent READ visualParent WRITE setVisualParent NOTIFY visualParentChanged)

+    // Name shown in the "Hide" action of streams; no such action when empty
+    Q_PROPERTY(QString hideableName READ hideableName WRITE setHideableName NOTIFY hideableNameChanged)
+
+    Q_PROPERTY(bool hidden READ isHidden WRITE setHidden NOTIFY hiddenChanged)
+
 public:
     explicit ListItemMenu(QObject *parent = nullptr);
     ~ListItemMenu() override;
@@ -76,6 +81,16 @@ public:
     void setVisualParent(QQuickItem *visualParent);
     Q_SIGNAL void visualParentChanged();

+    QString hideableName() const;
+    void setHideableName(const QString &hideableName);
+    Q_SIGNAL void hideableNameChanged();
+
+    bool isHidden() const;
+    void setHidden(bool hidden);
+    Q_SIGNAL void hiddenChanged();
+
+    Q_SIGNAL void hideToggled(bool hidden);
+
     void classBegin() override;
     void componentComplete() override;

@@ -92,6 +107,8 @@ private:
     bool m_complete = false;
     bool m_visible = false;
     bool m_hasContent = false;
+    bool m_hidden = false;
+    QString m_hideableName;
     QPointer<QQuickItem> m_visualParent;

     ItemType m_itemType = None;
-- 
